// 用户端API配置文件
import { getUserInfo, clearUserInfo } from './auth.js'

// 基础配置
const config = {
	// 开发环境API地址 - 微信开发工具中需要在「详情」-「本地设置」-「不校验合法域名」选项打勾
	baseURL: 'http://localhost:8080',
	// 生产环境API地址
	// baseURL: 'https://your-api-domain.com',
	// baseURL:'http://172.16.3.77:8080' ,
	
	// 请求超时时间
	timeout: 10000,
	
	// 请求头配置
	headers: {
		'Content-Type': 'application/json',
		'User-Type': 'customer' // 标识为用户端
	}
}

// 获取token
const getToken = () => {
	const userInfo = getUserInfo()
	return userInfo?.token || uni.getStorageSync('token') || ''
}

// 设置token
const setToken = (token) => {
	uni.setStorageSync('token', token)
}

// 清除token
const clearToken = () => {
	uni.removeStorageSync('token')
}

// 请求拦截器
const requestInterceptor = (options) => {
	// 添加token到请求头
	const token = getToken()
	if (token) {
		// 确保token是ASCII字符，如果包含非ASCII字符则进行编码
		const safeToken = encodeURIComponent(token)
		options.header = {
			...options.header,
			'Authorization': `Bearer ${safeToken}`
		}
	}
	
	// 添加基础配置
	options.url = config.baseURL + options.url
	options.timeout = config.timeout
	
	// 确保所有请求头的值都是ASCII字符
	const safeHeaders = {}
	
	// 特殊处理Content-Type，不进行编码
	if (config.headers['Content-Type']) {
		safeHeaders['Content-Type'] = config.headers['Content-Type']
	}
	
	// 处理其他请求头
	for (const key in config.headers) {
		if (config.headers.hasOwnProperty(key) && key !== 'Content-Type') {
			const value = config.headers[key]
			// 检查是否包含非ASCII字符，如果有则进行编码
			safeHeaders[key] = typeof value === 'string' ? encodeURIComponent(value) : value
		}
	}
	
	// 同样处理自定义请求头，特殊处理Content-Type
	for (const key in options.header) {
		if (options.header.hasOwnProperty(key)) {
			const value = options.header[key]
			// Content-Type不进行编码
			if (key === 'Content-Type') {
				safeHeaders[key] = value
			} else {
				// 检查是否包含非ASCII字符，如果有则进行编码
				safeHeaders[key] = typeof value === 'string' ? encodeURIComponent(value) : value
			}
		}
	}
	
	options.header = safeHeaders
	
	return options
}

// 响应拦截器
const responseInterceptor = (response) => {
	
	const { statusCode, data } = response
	
	// HTTP状态码检查
	if (statusCode >= 200 && statusCode < 300) {
		// 业务状态码检查
		if (data.code === 200) {
			return Promise.resolve(data)
		} else if (data && typeof data === 'object' && !data.hasOwnProperty('code')) {
			// 适配后端直接返回数据对象的情况（没有包装code字段）
			return Promise.resolve({ code: 200, data: data })
		} else if (data.code === 401) {
			// token过期或无效
			clearUserInfo()
			clearToken()
			uni.showToast({
				title: '登录已过期，请重新登录',
				icon: 'none'
			})
			// 跳转到登录页
			setTimeout(() => {
				uni.navigateTo({
					url: '/subpkg/auth/login'
				})
			}, 1500)
			return Promise.reject(data)
		} else {
			// 其他业务错误
			uni.showToast({
				title: data.message || '请求失败',
				icon: 'none'
			})
			return Promise.reject(data)
		}
	} else {
		// HTTP错误
		uni.showToast({
			title: '网络请求失败',
			icon: 'none'
		})
		return Promise.reject(response)
	}
}

// 通用请求方法
const request = (options) => {
	return new Promise((resolve, reject) => {
		// 请求拦截
		const interceptedOptions = requestInterceptor(options)
		
		uni.request({
			...interceptedOptions,
			success: (response) => {
				// 响应拦截
				responseInterceptor(response)
					.then(resolve)
					.catch(reject)
			},
			fail: (error) => {
				uni.showToast({
					title: '网络连接失败',
					icon: 'none'
				})
				reject(error)
			}
		})
	})
}

// GET请求
const get = (url, params = {}) => {
	return request({
		url,
		method: 'GET',
		data: params
	})
}

// POST请求
const post = (url, data = {}) => {
	return request({
		url,
		method: 'POST',
		data,
		header: {
			'Content-Type': 'application/json'
		}
	})
}

// PUT请求
const put = (url, data = {}) => {
	return request({
		url,
		method: 'PUT',
		data
	})
}

// DELETE请求
const del = (url, data = {}) => {
	return request({
		url,
		method: 'DELETE',
		data
	})
}

// 文件上传
const upload = (url, filePath, formData = {}) => {
	return new Promise((resolve, reject) => {
		const token = getToken()
		// 确保token是ASCII字符，如果包含非ASCII字符则进行编码
		const safeToken = token ? encodeURIComponent(token) : ''
		
		uni.uploadFile({
			url: config.baseURL + url,
			filePath,
			name: 'file',
			formData,
			header: {
				'Authorization': safeToken ? `Bearer ${safeToken}` : '',
				'User-Type': encodeURIComponent('customer'),
				// 文件上传需要设置正确的Content-Type
				'Content-Type': 'multipart/form-data'
			},
			success: (response) => {
				try {
					const data = JSON.parse(response.data)
					if (data.code === 200) {
						resolve(data)
					} else {
						uni.showToast({
							title: data.message || '上传失败',
							icon: 'none'
						})
						reject(data)
					}
				} catch (error) {
	
					reject(error)
				}
			},
			fail: (error) => {
				uni.showToast({
					title: '上传失败',
					icon: 'none'
				})
				reject(error)
			}
		})
	})
}

// 微信支付
const wxPay = (paymentData) => {
	return new Promise((resolve, reject) => {
		uni.requestPayment({
			provider: 'wxpay',
			timeStamp: paymentData.timeStamp,
			nonceStr: paymentData.nonceStr,
			package: paymentData.package,
			signType: paymentData.signType,
			paySign: paymentData.paySign,
			success: (res) => {
				resolve(res)
			},
			fail: (error) => {
				if (error.errMsg.includes('cancel')) {
					uni.showToast({
						title: '支付已取消',
						icon: 'none'
					})
				} else {
					uni.showToast({
						title: '支付失败',
						icon: 'none'
					})
				}
				reject(error)
			}
		})
	})
}

export {
	config,
	getToken,
	setToken,
	clearToken,
	request,
	get,
	post,
	put,
	del,
	upload,
	wxPay
}

export default {
	config,
	getToken,
	setToken,
	clearToken,
	request,
	get,
	post,
	put,
	del,
	upload,
	wxPay
}